SELECT CASE WHEN duration_sec >= 437 THEN 'high' WHEN duration_sec >= 172 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, SORT_ARRAY(COLLECT_SET(page)) AS page_list, COUNT(duration_sec) AS duration_sec_count, SORT_ARRAY(COLLECT_SET(event_type)) AS event_type_list FROM web_events WHERE duration_sec != 251 GROUP BY CASE WHEN duration_sec >= 437 THEN 'high' WHEN duration_sec >= 172 THEN 'mid' ELSE 'low' END ORDER BY 3;
